      setMessage('Você se matriculou com sucesso!')
    } else {
      setMessage('Você já está matriculado neste curso.')
    }
    setCourses([...db.getCourses()])
    setTimeout(() => setMessage(''), 2500)
  }

  return (
    <Layout
